/**
 * ModifyPlatformHTTPServiceRoute 请求参数
 */
export interface ModifyPlatformHTTPServiceRouteParams {
    /** 平台id */
    PlatformId: string;
    /** 域名路由信息（增量修改，对应字段不传则不修改） */
    Domain: HTTPServiceDomainParam;
}
/**
 * ModifyPlatformHTTPServiceRoute 返回结果
 */
export interface ModifyPlatformHTTPServiceRouteRes {
    /** 唯一请求 ID */
    RequestId: string;
}
/**
 * CreatePlatformHTTPServiceRoute 请求参数
 */
export interface CreatePlatformHTTPServiceRouteParams {
    /** 平台id */
    PlatformId: string;
    /** 域名路由信息。不传 Domain.Routes 时仅创建域名信息 */
    Domain: HTTPServiceDomainParam;
}
/**
 * CreatePlatformHTTPServiceRoute 返回结果
 */
export interface CreatePlatformHTTPServiceRouteRes {
    /** 归属权校验不通过时返回的验证指引，按指引配置 DNS 或文件验证后，
     * 可调用 verifyPlatformHttpServiceRoute 验证归属权是否通过 */
    OwnershipVerification?: OwnershipVerificationInfo;
    /** 唯一请求 ID */
    RequestId: string;
}
/**
 * VerifyPlatformHTTPServiceRoute 请求参数
 */
export interface VerifyPlatformHTTPServiceRouteParams {
    /** 平台id */
    PlatformId: string;
    /** 域名路由信息 */
    Domain: HTTPServiceDomainParam;
}
/**
 * VerifyPlatformHTTPServiceRoute 返回结果
 */
export interface VerifyPlatformHTTPServiceRouteRes {
    /** 前置校验总开关。所有启用的检查项均为 PASS 或 SKIPPED 时为 true，
     * 任一检查项为 FAIL 时为 false */
    Passed?: boolean;
    /** 域名归属权校验结果 */
    Ownership?: VerifyHttpServiceRouteCheckItem;
    /** 证书校验结果；CertId 为空时 Status=SKIPPED */
    Cert?: VerifyHttpServiceRouteCheckItem;
    /** 域名/路径数量配额校验结果 */
    Quota?: VerifyHttpServiceRouteCheckItem;
    /** 同域名下路由路径冲突校验结果 */
    RouteConflict?: VerifyHttpServiceRouteCheckItem;
    /** 域名被其他环境占用校验结果 */
    DomainConflict?: VerifyHttpServiceRouteCheckItem;
    /** 内部域名且非内部账号校验结果 */
    InternalAccount?: VerifyHttpServiceRouteCheckItem;
    /** 域名黑名单校验结果 */
    Blacklist?: VerifyHttpServiceRouteCheckItem;
    /** AccessType=CDN 时 CDN 资源存在性/状态校验结果（含 ICP 未备案提示） */
    CDNResource?: VerifyHttpServiceRouteCheckItem;
    /** AccessType=EO 时的 EdgeOne 预检结果（域名冲突/备案/归属权） */
    EO?: VerifyHttpServiceRouteCheckItem;
    /** 唯一请求 ID */
    RequestId: string;
}
/**
 * DeletePlatformHTTPServiceRoute 请求参数
 */
export interface DeletePlatformHTTPServiceRouteParams {
    /** 平台id */
    PlatformId: string;
    /** 域名 */
    Domain: string;
    /** 路径列表。为空则表示删除此域名及所有路由；不为空则仅删除对应的 path 路由 */
    Paths?: string[];
}
/**
 * DeletePlatformHTTPServiceRoute 返回结果
 */
export interface DeletePlatformHTTPServiceRouteRes {
    /** 唯一请求 ID */
    RequestId: string;
}
/**
 * DescribePlatformHTTPServiceRoute 请求参数
 */
export interface DescribePlatformHTTPServiceRouteParams {
    /** 平台id */
    PlatformId: string;
    /** 过滤条件。可过滤: Domain、Path、DomainType、UpstreamResourceType。
     * 过滤条件数量限制为 10，Values 单条不超过 100 */
    Filters?: HTTPServiceRouteFilter[];
    /** 分页偏移量，默认 0 */
    Offset?: number;
    /** 分页限制，默认 20，最大值 1000 */
    Limit?: number;
}
/**
 * DescribePlatformHTTPServiceRoute 返回结果
 */
export interface DescribePlatformHTTPServiceRouteRes {
    /** 域名路由信息列表 */
    Domains?: HTTPServiceDomain[];
    /** 自定义接入的源站域名（HTTPService接入层域名） */
    OriginDomain: string;
    /** 域名总数，分页查询使用总数判断是否已经拉取到所有数据 */
    TotalCount: number;
    /** 唯一请求 ID */
    RequestId: string;
}
